def dist(a,b):
    la1,lo1,la2,lo2=map(math.radians,[a[1],a[0],b[1],b[0]]);h=math.sin((la2-la1)/2)**2+math.cos(la1)*math.cos(la2)*math.sin((lo2-lo1)/2)**2;return 12742*math.asin(math.sqrt(h))
def hours(a,b): return max(2,round(dist(C[a]['co'],C[b]['co'])/800))
if __name__=='__main__':
    for c in C.values():
        assert len(c['nxt'])==3 and all(n in C and n!=c['id'] for n in c['nxt']),c['id']
    def routes(s):
        out=[]
        def go(path):
            if len(path)==6: out.append(tuple(path)); return
            for n in C[path[-1]]['nxt']:
                if n in path: continue
                if len(path)<5 and C[n]['attr'] in [C[x]['attr'] for x in path]: continue
                go(path+[n])
        go([s]); return out
    tot=0;ends=set();mid=set()
    for s in [c for c in C if C[c]['start']]:
        r=routes(s); tot+=len(r); ends|={x[-1] for x in r}; mid|={y for x in r for y in x}
        print(s,len(r))
    print('total',tot,'finals',sorted(ends),'unused',set(C)-mid)
    print('reach in', {c:[x for x in C if c in C[x]['nxt']] for c in C})
    json.dump(dict(C=C,CLUE=CLUE,FINAL=FINAL,ATTR=ATTR),open('data.json','w'),ensure_ascii=False)
